package co.serviasigna.domain;

import jakarta.persistence.*;

/**
 * Una posición del historial de GPS (tabla UBICACION_GPS).
 * <p>
 * Se depura sola después de N días (RNF-10) y sirve para el indicador I4 (km por servicio).
 * <p>
 * EN: A position in the GPS history (UBICACION_GPS table).
 * <p>
 * It is cleaned up automatically after N days (RNF-10) and is used for indicator I4 (km per delivery).
 */
@Entity
@Table(name = "UBICACION_GPS")
public class GpsLocation {
    /** El identificador que genera Oracle. EN: The identifier generated by Oracle. */
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id;
    /** El id del domiciliario. EN: The courier id. */
    @Column(name = "DOMICILIARIO_ID", nullable = false) private Long courierId;
    /** La latitud. EN: The latitude. */
    @Column(name = "LAT", nullable = false) private double lat;
    /** La longitud. EN: The longitude. */
    @Column(name = "LNG", nullable = false) private double lng;
    /** La precisión en metros. EN: The accuracy in meters. */
    @Column(name = "PRECISION_M") private Double accuracyM;
    /** El estado operativo en ese momento. EN: The operating status at that moment. */
    @Column(name = "ESTADO_OPERATIVO", nullable = false, length = 20) private CourierStatus courierStatus;
    /** La hora en que el celular tomó la posición. EN: The time the phone took the position. */
    @Convert(converter = MinutesConverter.class) @Column(name = "FECHA_CAPTURA", nullable = false) private Double capturedAt;
    /** La hora en que llegó al servidor. EN: The time it reached the server. */
    @Convert(converter = MinutesConverter.class) @Column(name = "FECHA_RECEPCION", nullable = false) private Double receivedAt;

    /**
     * Constructor vacío que exige JPA para leer la fila de la base de datos.
     * <p>
     * EN: Empty constructor required by JPA to read the row from the database.
     */
    protected GpsLocation() {}

    /**
     * Crea una posición del historial.
     * <p>
     * EN: Creates a history position.
     *
     * @param courierId id del domiciliario / courier id
     * @param p punto reportado / reported point
     * @param accuracyM precisión en metros, puede ser null / accuracy in meters, may be null
     * @param status estado operativo en ese momento / operating status at that moment
     * @param capture hora en que el celular tomó la posición / time the phone took the position
     * @param reception hora en que llegó al servidor / time it reached the server
     */
    public GpsLocation(long courierId, GeoPoint p, Double accuracyM, CourierStatus status, double capture, double reception) {
        this.courierId = courierId; this.lat = p.lat(); this.lng = p.lng(); this.accuracyM = accuracyM;
        this.courierStatus = status; this.capturedAt = capture; this.receivedAt = reception;
    }

    /**
     * Devuelve el identificador que genera Oracle.
     * <p>
     * EN: Returns the identifier generated by Oracle.
     *
     * @return el identificador que genera Oracle / the identifier generated by Oracle
     */
    public Long getId() { return id; }

    /**
     * Devuelve el id del domiciliario.
     * <p>
     * EN: Returns the courier id.
     *
     * @return el id del domiciliario / the courier id
     */
    public Long getCourierId() { return courierId; }

    /**
     * Devuelve el punto reportado.
     * <p>
     * EN: Returns the reported point.
     *
     * @return el punto / the point
     */
    public GeoPoint point() { return new GeoPoint(lat, lng); }

    /**
     * Devuelve la precisión en metros.
     * <p>
     * EN: Returns the accuracy in meters.
     *
     * @return la precisión en metros / the accuracy in meters
     */
    public Double getAccuracyM() { return accuracyM; }

    /**
     * Devuelve el estado operativo en ese momento.
     * <p>
     * EN: Returns the operating status at that moment.
     *
     * @return el estado operativo en ese momento / the operating status at that moment
     */
    public CourierStatus getCourierStatus() { return courierStatus; }

    /**
     * Devuelve la hora en que el celular tomó la posición.
     * <p>
     * EN: Returns the time the phone took the position.
     *
     * @return la hora en que el celular tomó la posición / the time the phone took the position
     */
    public Double getCapturedAt() { return capturedAt; }

    /**
     * Devuelve la hora en que llegó al servidor.
     * <p>
     * EN: Returns the time it reached the server.
     *
     * @return la hora en que llegó al servidor / the time it reached the server
     */
    public Double getReceivedAt() { return receivedAt; }
}
